mapper.select:
select a.id as courseid, a.curriculum, a.author, a.synopsis, a.subjectid, a.picture, a.integral, a.browse, a.upvote, a.discussid,b.splandt,b.plandt from  (select id, curriculum, author, synopsis, subjectid, picture, integral, browse, upvote, discussid from common_course where  deleted =0 and   id in(select courseid  from common_course_plan where studenterId=#{studenterId} and deleted=0  and plantype=0 and splandt between  #{stime} and #{etime} || plandt between    #{stime} and #{etime})) a
 left join common_course_plan  b on a.id=b.courseid
